api.look('agent');
const cx=api.w/2, cy=api.h/2-40;
const k=api.ease(api.seg(t,0,1));
api.rect(cx-130,cy-230,260,460,{r:32,c:'fg',w:4,k});
api.text('Settings',cx,cy-190,{size:30,weight:700,align:'center',k:api.seg(t,0.8,1.6)});
const rows=['Profile','Notifications','Help','Log out'];
rows.forEach((r,i)=>{
  const kk=api.stag(t,i,{gap:0.25,dur:0.5,from:1});
  api.rect(cx-105,cy-140+i*70,210,50,{r:14,c:i==3?'bad':'a2',w:3,k:kk});
  api.text(r,cx-85,cy-115+i*70,{size:20,c:i==3?'bad':'fg',k:kk});
});
api.say('Settings, before today',0.3,3.3);

api.look('agent');
const cx=api.w/2, cy=api.h/2-40;
const rowsB=['Profile','Notifications','Help','Log out'];
api.rect(cx-130,cy-230,260,460,{r:32,c:'fg',w:4});
api.text('Settings',cx,cy-190,{size:30,weight:700,align:'center'});
// Help removed
const kh=api.seg(t,0.3,1.5);
const hy=cy-140+2*70;
api.rect(cx-105,hy,210,50,{r:14,c:'a2',w:3,a:1-kh});
api.text('Help',cx-85,hy+25,{size:20,a:1-kh});
api.line(cx-110,hy+25,cx+110,hy+25,{c:'bad',w:4,k:api.seg(t,0.2,0.8)});
api.text('Removed',cx+95,hy-14,{size:18,c:'bad',align:'center',k:api.seg(t,1,1.8)});
// Dark mode added at position 3 slot
const kd=api.back(api.seg(t,2,3));
const dy=cy-140+2*70;
api.rect(cx-105,dy,210,50,{r:14,c:'good',w:3,k:kd});
api.text('Dark mode',cx-85,dy+25,{size:20,c:'good',k:kd});
api.rect(cx+50,dy+13,44,24,{r:12,c:'good',w:3,fill:'good',k:kd});
api.circle(cx+82,dy+25,8,{c:'fg',fill:'fg',k:kd});
api.text('Added',cx+95,dy-14,{size:18,c:'good',align:'center',k:api.seg(t,3,3.8)});
// Log out moves to bottom
const km=api.ease(api.seg(t,3.8,5.2));
const ly=api.lerp(cy-140+3*70,cy+170,km);
api.rect(cx-105,ly,210,50,{r:14,c:'bad',w:3});
api.text('Log out',cx-85,ly+25,{size:20,c:'bad'});
api.arrow(cx+120,cy+70,cx+120,cy+165,{c:'accent',w:3,k:api.seg(t,3.8,4.6)});
api.say('Dark mode added, Help gone',0.3,3.4);
api.say('Log out moved down',3.8,5.8);

api.look('agent');
const cx=api.w/2;
const items=[['Log out moved to bottom','accent',()=>api.shape('arrow',cx-120,300,40,{c:'accent',w:3,rot:1.57})],['Dark mode added','good',()=>api.shape('moon',cx-120,420,40,{c:'good',w:3})],['Help removed','bad',()=>api.shape('cross',cx-120,540,40,{c:'bad',w:3})]];
items.forEach((it,i)=>{
  const k=api.stag(t,i,{gap:0.8,dur:0.7,from:0.2});
  api.circle(cx-120,300+i*120,34,{c:it[1],w:3,k});
  api.shape(['arrow','moon','cross'][i],cx-120,300+i*120,34,{c:it[1],w:3,k});
  api.text(it[0],cx-70,300+i*120,{size:22,c:'fg',k,maxw:200});
});
api.say('Three changes today',0.3,4.8);
